Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
RDMA/uverbs: Validate wqe_size before using it in
 ib_uverbs_post_send

ib_uverbs_post_send() uses cmd.wqe_size from userspace without any
validation before passing it to kmalloc() and using the allocated
buffer as struct ib_uverbs_send_wr.

If a user provides a small wqe_size value (e.g., 1), kmalloc() will
succeed, but subsequent accesses to user_wr->opcode, user_wr->num_sge,
and other fields will read beyond the allocated buffer, resulting in
an out-of-bounds read from kernel heap memory. This could potentially
leak sensitive kernel information to userspace.

Additionally, providing an excessively large wqe_size can trigger a
WARNING in the memory allocation path, as reported by syzkaller.

This is inconsistent with ib_uverbs_unmarshall_recv() which properly
validates that wqe_size >= sizeof(struct ib_uverbs_recv_wr) before
proceeding.

Add the same validation for ib_uverbs_post_send() to ensure wqe_size
is at least sizeof(struct ib_uverbs_send_wr).

Fixes: c3bea3d2dc53 ("RDMA/uverbs: Use the iterator for ib_uverbs_unmarshall_recv()")
Signed-off-by: Yi Liu <liuy22@mails.tsinghua.edu.cn>
Link: https://patch.msgid.link/20260122142900.2356276-2-liuy22@mails.tsinghua.edu.cn
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
The function ib_uverbs_post_send() does not validate the wqe_size value from userspace before using it to allocate memory and interpret the buffer as struct ib_uverbs_send_wr. This allows a user to provide a wqe_size smaller than the structure size, causing out-of-bounds reads, or an excessively large wqe_size triggering memory allocation warnings.

Here is the patch:

 static int ib_uverbs_post_send(struct uverbs_attr_bundle *attrs)
 {
 	struct ib_uverbs_post_send      cmd;
 	struct ib_uverbs_post_send_resp resp;
 	struct ib_uverbs_send_wr       *user_wr;
 	struct ib_send_wr              *wr = NULL, *last, *next;
 	const struct ib_send_wr	       *bad_wr;
 	struct ib_qp                   *qp;
 	int                             i, sg_ind;
 	int				is_ud;
 	int ret, ret2;
 	size_t                          next_size;
 	const struct ib_sge __user *sgls;
 	const void __user *wqes;
 	struct uverbs_req_iter iter;

 	ret = uverbs_request_start(attrs, &iter, &cmd, sizeof(cmd));
 	if (ret)
 		return ret;
 	wqes = uverbs_request_next_ptr(&iter, size_mul(cmd.wqe_size,
 						       cmd.wr_count));
 	if (IS_ERR(wqes))
 		return PTR_ERR(wqes);
 	sgls = uverbs_request_next_ptr(&iter,
 				       size_mul(cmd.sge_count,
 						sizeof(struct ib_uverbs_sge)));
 	if (IS_ERR(sgls))
 		return PTR_ERR(sgls);
 	ret = uverbs_request_finish(&iter);
 	if (ret)
 		return ret;

-	user_wr = kmalloc(cmd.wqe_size, GFP_KERNEL);
+	if (cmd.wqe_size < sizeof(struct ib_uverbs_send_wr))
+		return -EINVAL;
+
+	user_wr = kmalloc(cmd.wqe_size, GFP_KERNEL | __GFP_NOWARN);
 	if (!user_wr)
 		return -ENOMEM;

 	qp = uobj_get_obj_read(qp, UVERBS_OBJECT_QP, cmd.qp_handle, attrs);
 	if (IS_ERR(qp)) {
 		ret = PTR_ERR(qp);
 		goto out;
 	}

 	is_ud = qp->qp_type == IB_QPT_UD;
 	sg_ind = 0;
 	last = NULL;
 	for (i = 0; i < cmd.wr_count; ++i) {
 		if (copy_from_user(user_wr, wqes + i * cmd.wqe_size,
 				   cmd.wqe_size)) {
 			ret = -EFAULT;
 			goto out_put;
 		}

 		if (user_wr->num_sge + sg_ind > cmd.sge_count) {
 			ret = -EINVAL;
 			goto out_put;
 		}

 		if (is_ud) {
 			struct ib_ud_wr *ud;

 			if (user_wr->opcode != IB_WR_SEND &&
 			    user_wr->opcode != IB_WR_SEND_WITH_IMM) {
 				ret = -EINVAL;
 				goto out_put;
 			}

 			next_size = sizeof(*ud);
 			ud = alloc_wr(next_size, user_wr->num_sge);
 			if (!ud) {
 				ret = -ENOMEM;
 				goto out_put;
 			}

 			ud->ah = uobj_get_obj_read(ah, UVERBS_OBJECT_AH,
 						   user_wr->wr.ud.ah, attrs);
 			if (IS_ERR(ud->ah)) {
 				ret = PTR_ERR(ud->ah);
 				kfree(ud);
 				goto out_put;
 			}
 			ud->remote_qpn = user_wr->wr.ud.remote_qpn;
 			ud->remote_qkey = user_wr->wr.ud.remote_qkey;

 			next = &ud->wr;
 		} else if (user_wr->opcode == IB_WR_RDMA_WRITE_WITH_IMM ||
 			   user_wr->opcode == IB_WR_RDMA_WRITE ||
 			   user_wr->opcode == IB_WR_RDMA_READ) {
 			struct ib_rdma_wr *rdma;

 			next_size = sizeof(*rdma);
 			rdma = alloc_wr(next_size, user_wr->num_sge);
 			if (!rdma) {
 				ret = -ENOMEM;
 				goto out_put;
 			}

 			rdma->remote_addr = user_wr->wr.rdma.remote_addr;
 			rdma->rkey = user_wr->wr.rdma.rkey;

 			next = &rdma->wr;
 		} else if (user_wr->opcode == IB_WR_ATOMIC_CMP_AND_SWP ||
 			   user_wr->opcode == IB_WR_ATOMIC_FETCH_AND_ADD) {
 			struct ib_atomic_wr *atomic;

 			next_size = sizeof(*atomic);
 			atomic = alloc_wr(next_size, user_wr->num_sge);
 			if (!atomic) {
 				ret = -ENOMEM;
 				goto out_put;
 			}

 			atomic->remote_addr = user_wr->wr.atomic.remote_addr;
 			atomic->compare_add = user_wr->wr.atomic.compare_add;
 			atomic->swap = user_wr->wr.atomic.swap;
 			atomic->rkey = user_wr->wr.atomic.rkey;

 			next = &atomic->wr;
 		} else if (user_wr->opcode == IB_WR_SEND ||
 			   user_wr->opcode == IB_WR_SEND_WITH_IMM ||
 			   user_wr->opcode == IB_WR_SEND_WITH_INV) {
 			next_size = sizeof(*next);
 			next = alloc_wr(next_size, user_wr->num_sge);
 			if (!next) {
 				ret = -ENOMEM;
 				goto out_put;
 			}
 		} else {
 			ret = -EINVAL;
 			goto out_put;
 		}

 		if (user_wr->opcode == IB_WR_SEND_WITH_IMM ||
 		    user_wr->opcode == IB_WR_RDMA_WRITE_WITH_IMM) {
 			next->ex.imm_data =
 					(__be32 __force) user_wr->ex.imm_data;
 		} else if (user_wr->opcode == IB_WR_SEND_WITH_INV) {
 			next->ex.invalidate_rkey = user_wr->ex.invalidate_rkey;
 		}

 		if (!last)
 			wr = next;
 		else
 			last->next = next;
 		last = next;

 		next->next       = NULL;
 		next->wr_id      = user_wr->wr_id;
 		next->num_sge    = user_wr->num_sge;
 		next->opcode     = user_wr->opcode;
 		next->send_flags = user_wr->send_flags;

 		if (next->num_sge) {
 			next->sg_list = (void *) next +
 				ALIGN(next_size, sizeof(struct ib_sge));
 			if (copy_from_user(next->sg_list, sgls + sg_ind,
 					   next->num_sge *
 						   sizeof(struct ib_sge))) {
 				ret = -EFAULT;
 				goto out_put;
 			}
 			sg_ind += next->num_sge;
 		} else
 			next->sg_list = NULL;
 	}

 	resp.bad_wr = 0;
 	ret = qp->device->ops.post_send(qp->real_qp, wr, &bad_wr);
 	if (ret)
 		for (next = wr; next; next = next->next) {
 			++resp.bad_wr;
 			if (next == bad_wr)
 				break;
 		}

 	ret2 = uverbs_response(attrs, &resp, sizeof(resp));
 	if (ret2)
 		ret = ret2;

 out_put:
 	rdma_lookup_put_uobject(&qp->uobject->uevent.uobject,
 				UVERBS_LOOKUP_READ);

 	while (wr) {
 		if (is_ud && ud_wr(wr)->ah)
 			uobj_put_obj_read(ud_wr(wr)->ah);
 		next = wr->next;
 		kfree(wr);
 		wr = next;
 	}

 out:
 	kfree(user_wr);

 	return ret;
 }



